import React, { useState, useEffect, useCallback, useRef } from 'react';
import { isPositionClosed } from '../constants/recruitment';
import { Form, Button } from 'react-bootstrap';
import { useSiteConfig } from '../contexts/SiteConfigContext';

// Helper component for collapsible section headers (remains the same)
const CollapsibleHeader = ({ title, isOpen, onToggle, sectionId }) => (
    <Button
        variant="link"
        className="section-toggle"
        onClick={onToggle}
        aria-expanded={isOpen}
        aria-controls={`collapse-${sectionId}`}
        style={{
            fontWeight: 'bold',
            marginTop: '1rem',
            padding: '0.5rem 0',
            textDecoration: 'none',
            color: 'inherit',
            display: 'flex',
            justifyContent: 'space-between',
            width: '100%',
            textAlign: 'left',
            border: 'none',
            background: 'none'
        }}
    >
        {title}
        <i className={`fas ${isOpen ? 'fa-chevron-up' : 'fa-chevron-down'}`} style={{ marginLeft: '10px' }}></i>
    </Button>
);

const LOCAL_STORAGE_KEY = 'physicianApplicationFormData';
const EXPIRY_DURATION_MS = 5 * 24 * 60 * 60 * 1000; // 5 days

const physicianFormFields = [
    'recruitmentPosition', 'applicantTitleAndFullName', 'genderMale', 'genderFemale', 'genderOther',
    'applicantGenderOtherText', 'applicantDOB', 'applicantBirthPlace', 'applicantAddress', 'applicantPhone', 'applicantEmail', // MODIFIED: Split DOB field
    'locationPHMC', 'locationPBC', 'applicantMedicalConditions', 'citizenUS', 'citizenPermanent', 'citizenNone',
    'eduHighSchool', 'eduCertificate', 'eduDiploma', 'eduAssociate', 'eduBachelor', 'eduMaster', 'eduDoctorate',
    'applicantSchoolName', 'applicantEnrollmentTerm', 'applicantMajor', 'applicantLanguages',
    'applicantPrevEmployment', 'applicantPrevDuties', 'applicantPrevDismissalReason',
    'applicantMotivationLetter', 'oocUcpName', 'oocForumName', 'oocDiscord', 'oocTimezone',
    'oocMedicalExperience'
];

const PhysicianFields = ({
    formData,
    handleChange,
    setFormData,
    physicianRecruitmentDetails,
    handleImageUpload, // Added prop
    isUploading        // Added prop
}) => {
    // Choix « PBC » masqué quand les formulaires PBC sont désactivés (panneau admin → Affichage).
    const { pbcEnabled } = useSiteConfig();
    const positionDetails = physicianRecruitmentDetails || {};

    const [isPersonalInfoOpen, setIsPersonalInfoOpen] = useState(true);
    const [isEducationalInfoOpen, setIsEducationalInfoOpen] = useState(true);
    const [isEmploymentInfoOpen, setIsEmploymentInfoOpen] = useState(true);
    const [isMotivationalLetterOpen, setIsMotivationalLetterOpen] = useState(true);
    const [isOocInfoOpen, setIsOocInfoOpen] = useState(true);

    const prevCompletionStatusOnBlurRef = useRef({});

    useEffect(() => {
        const sections = ['personalInfo', 'educationalInfo', 'employmentInfo', 'motivationalLetter', 'oocInfo'];
        sections.forEach(sectionId => {
            if (prevCompletionStatusOnBlurRef.current[sectionId] === undefined) {
                prevCompletionStatusOnBlurRef.current[sectionId] = false;
            }
        });
    }, []);

    useEffect(() => {
        try {
            const savedDataString = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (savedDataString) {
                const savedData = JSON.parse(savedDataString);
                if (savedData && savedData.data && savedData.timestamp) {
                    if (Date.now() - savedData.timestamp < EXPIRY_DURATION_MS) {
                        const relevantSavedData = {};
                        physicianFormFields.forEach(field => {
                            if (savedData.data.hasOwnProperty(field)) {
                                relevantSavedData[field] = savedData.data[field];
                            }
                        });
                        setFormData(prev => ({ ...prev, ...relevantSavedData }));
                    } else {
                        localStorage.removeItem(LOCAL_STORAGE_KEY);
                    }
                }
            }
        } catch (error) {
            console.error("Error loading physician form data from localStorage:", error);
            localStorage.removeItem(LOCAL_STORAGE_KEY);
        }
    }, [setFormData]);

    useEffect(() => {
        try {
            const dataToSave = {};
            physicianFormFields.forEach(field => {
                if (formData.hasOwnProperty(field)) {
                    dataToSave[field] = formData[field];
                }
            });
            const physicianDataWithTimestamp = {
                data: dataToSave,
                timestamp: Date.now()
            };
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(physicianDataWithTimestamp));
        } catch (error) {
            console.error("Error saving physician form data to localStorage:", error);
        }
    }, [formData]);

    const checkFieldsCompletion = useCallback((fieldsToCheck) => {
        for (const field of fieldsToCheck) {
            if (typeof field === 'string') {
                const value = formData[field];
                if (typeof value === 'string' && !value.trim()) return false;
                if (typeof value === 'boolean' && !value) return false;
                if (value === undefined || value === null) return false;
            } else if (typeof field === 'object' && field.anyOf) {
                if (!field.anyOf.some(subField => formData[subField])) return false;
            } else if (typeof field === 'object' && field.conditional) {
                if (formData[field.conditional.if.field] === field.conditional.if.value) {
                    const conditionalValue = formData[field.conditional.then.field];
                    if (typeof conditionalValue === 'string' && !conditionalValue.trim()) return false;
                    if (conditionalValue === undefined || conditionalValue === null) return false;
                }
            }
        }
        return true;
    }, [formData]);

    const sectionRequiredFields = {
        personalInfo: [
            'recruitmentPosition', 'applicantTitleAndFullName',
            { anyOf: ['genderMale', 'genderFemale', 'genderOther'] },
            { conditional: { if: { field: 'genderOther', value: true }, then: { field: 'applicantGenderOtherText' } } },
            'applicantDOB', 'applicantBirthPlace', // MODIFIED: Split DOB field
            'applicantAddress', 'applicantPhone', 'applicantEmail',
            { anyOf: ['locationPHMC', 'locationPBC'] },
            'applicantMedicalConditions',
            { anyOf: ['citizenUS', 'citizenPermanent', 'citizenNone'] }
        ],
        educationalInfo: [
            { anyOf: ['eduHighSchool', 'eduCertificate', 'eduDiploma', 'eduAssociate', 'eduBachelor', 'eduMaster', 'eduDoctorate'] },
            'applicantSchoolName', 'applicantEnrollmentTerm', 'applicantMajor', 'applicantLanguages'
        ],
        employmentInfo: [
            'applicantPrevEmployment', 'applicantPrevDuties',
        ],
        motivationalLetter: ['applicantMotivationLetter'],
        oocInfo: [
            'oocUcpName', 'oocForumName', 'oocDiscord', 'oocTimezone',
            'oocMedicalExperience'
        ]
    };

    const handleSectionFieldBlur = useCallback((sectionId, isOpenState, setIsOpenFunction, requiredFieldsKey) => {
        const isNowComplete = checkFieldsCompletion(sectionRequiredFields[requiredFieldsKey]);
        const wasCompleteAtLastBlur = prevCompletionStatusOnBlurRef.current[sectionId] === true;

        if (isOpenState && isNowComplete && !wasCompleteAtLastBlur) {
            setIsOpenFunction(false);
        }
        prevCompletionStatusOnBlurRef.current[sectionId] = isNowComplete;
    }, [checkFieldsCompletion, sectionRequiredFields]);


    return (
        <>

            {/* --- 1. Personal Information --- */}
            <CollapsibleHeader
                title="1. Informations personnelles"
                isOpen={isPersonalInfoOpen}
                onToggle={() => setIsPersonalInfoOpen(!isPersonalInfoOpen)}
                sectionId="personal-info"
            />
            {isPersonalInfoOpen && (
                <div id="collapse-personal-info" style={{ paddingTop: '0.5rem' }}>
                    <Form.Group className="mb-3">
                        <Form.Label>1.0 Poste pour lequel vous postulez</Form.Label>
                        <Form.Select
                            name="recruitmentPosition"
                            value={formData.recruitmentPosition || ''}
                            onChange={handleChange}
                            onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            className="form-control mb-4" // Added mb-4
                        >
                            <option value="">Sélectionner un poste en médecine...</option>
                            {Object.entries(positionDetails).map(([key, position]) => (
                                <option
                                    key={key}
                                    value={key}
                                    style={isPositionClosed(position) ? { color: 'red', fontWeight: 'bold' } : {}}
                                    disabled={isPositionClosed(position)}
                                >
                                    {position.nom}{isPositionClosed(position) ? " (Candidatures fermées)" : ""}
                                </option>
                            ))}
                        </Form.Select>
                         {!formData.recruitmentPosition && <div className="invalid-feedback d-block">Le poste est requis.</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>1.1 Titre et nom complet</Form.Label>
                        <Form.Control
                            type="text"
                            name="applicantTitleAndFullName"
                            value={formData.applicantTitleAndFullName || ''}
                            onChange={handleChange}
                            onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            placeholder="Prénom (Deuxième Prénom) & Nom"
                            className="form-control mb-4" // Added mb-4
                        />
                        {!formData.applicantTitleAndFullName && <div className="invalid-feedback d-block">Le titre et nom complet est requis.</div>}
                    </Form.Group>

                    <Form.Group className="mb-1"> {/* Keep mb-1 on Form.Group for tighter group, or change to mb-3 if desired */}
                        <Form.Label>1.2 Genre</Form.Label>
                        <div
                            style={{ display: 'flex', gap: '1rem' }}
                            className="gender-checkbox-group mb-4" // Added mb-4 to the div wrapping checkboxes
                            onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                        >
                            <Form.Check
                                inline type="checkbox" label="Homme" name="genderMale"
                                checked={formData.genderMale || false} onChange={handleChange}
                            />
                            <Form.Check
                                inline type="checkbox" label="Femme" name="genderFemale"
                                checked={formData.genderFemale || false} onChange={handleChange}
                            />
                            <Form.Check
                                inline type="checkbox" label="Autre" name="genderOther"
                                checked={formData.genderOther || false} onChange={handleChange}
                            />
                        </div>
                        {/* This validation message appears if no gender is selected */}
                        {!(formData.genderMale || formData.genderFemale || formData.genderOther) && <div className="invalid-feedback d-block">La sélection du genre est requise.</div>}

                        {formData.genderOther && (
                            <Form.Control
                                type="text" name="applicantGenderOtherText" value={formData.applicantGenderOtherText || ''}
                                onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                                placeholder="Préciser autre genre"
                                className="mt-2 form-control mb-4" // Added mb-4, mt-2 is for spacing from checkboxes
                            />
                        )}
                        {formData.genderOther && !formData.applicantGenderOtherText && <div className="invalid-feedback d-block">La précision pour 'Autre' genre est requise.</div>}
                    </Form.Group>

                    {/* MODIFIED: Split Date & Place of Birth */}
                    <Form.Group className="mb-3">
                        <Form.Label>1.3 Date de naissance</Form.Label>
                        <Form.Control
                            type="date" name="applicantDOB" value={formData.applicantDOB || ''}
                            onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            className="form-control mb-4"
                        />
                        {!formData.applicantDOB && <div className="invalid-feedback d-block">La date de naissance est requise.</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>1.4 Lieu de naissance (Ville)</Form.Label>
                        <Form.Control
                            type="text" name="applicantBirthPlace" value={formData.applicantBirthPlace || ''}
                            onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            placeholder="Ville de naissance"
                            className="form-control mb-4"
                        />
                        {!formData.applicantBirthPlace && <div className="invalid-feedback d-block">Le lieu de naissance (Ville) est requis.</div>}
                    </Form.Group>
                    {/* END MODIFIED: Split Date & Place of Birth */}

                    <Form.Group className="mb-3">
                        <Form.Label>1.5 Adresse du domicile</Form.Label> {/* MODIFIED: Label number */}
                        <Form.Control
                            type="text" name="applicantAddress" value={formData.applicantAddress || ''}
                            onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            placeholder="Adresse (Numéro, Étage, Rue)"
                            className="form-control mb-4" // Added mb-4
                        />
                        {!formData.applicantAddress && <div className="invalid-feedback d-block">L'adresse du domicile est requise.</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>1.6 Coordonnées</Form.Label> {/* MODIFIED: Label number */}
                        <div style={{ display: 'flex', gap: '10px' }}>
                            <Form.Control
                                type="text" name="applicantPhone" value={formData.applicantPhone || ''}
                                onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                                placeholder="Numéro de téléphone"
                                className="form-control mb-4"
                            />
                            <Form.Control
                                type="email" name="applicantEmail" value={formData.applicantEmail || ''}
                                onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                                placeholder="Adresse email (ex: prenomnom@mail.eyefind.fr)"
                                className="form-control mb-4"
                            />
                        </div>
                        {(!formData.applicantPhone || !formData.applicantEmail) && <div className="invalid-feedback d-block">Le téléphone et l'email sont requis.</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>1.7 Lieu d'emploi souhaité</Form.Label>
                        <div
                            onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            className="mb-4" // Added mb-4 to the div wrapping checkboxes
                        >
                            <Form.Check
                                inline type="checkbox" label="Pillbox Hill Medical Center (Ville de Los Santos)" name="locationPHMC"
                                checked={formData.locationPHMC || true} onChange={handleChange}
                            />
                            {pbcEnabled && (<Form.Check
                                inline type="checkbox" label="PHMC Paleto Bay Clinic (Paleto Bay)" name="locationPBC"
                                checked={formData.locationPBC || false} disabled //onChange={handleChange}
                            />)}
                        </div>
                        {!(formData.locationPHMC || formData.locationPBC) && <div className="invalid-feedback d-block">Au moins un lieu doit être sélectionné.</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>1.8 Avez-vous une condition médicale diagnostiquée?</Form.Label> {/* MODIFIED: Label number */}
                        <Form.Control
                            as="textarea" rows={3} name="applicantMedicalConditions" value={formData.applicantMedicalConditions || ''}
                            onChange={handleChange} onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            placeholder="Listez toute information médicale pertinente, ou N/A"
                            className="form-control mb-4" // Added mb-4
                        />
                        {!formData.applicantMedicalConditions && <div className="invalid-feedback d-block">Ce champ est requis (entrez N/A si aucun).</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>1.9 Citoyenneté</Form.Label> {/* MODIFIED: Label number */}
                        <div
                            onBlur={() => handleSectionFieldBlur('personalInfo', isPersonalInfoOpen, setIsPersonalInfoOpen, 'personalInfo')}
                            className="mb-4" // Added mb-4 to the div wrapping checkboxes
                        >
                            <Form.Check
                                inline type="checkbox" label="Citoyen des États-Unis" name="citizenUS"
                                checked={formData.citizenUS || false} onChange={handleChange}
                            />
                            <Form.Check
                                inline type="checkbox" label="Statut de résident permanent étranger et demande de citoyenneté américaine" name="citizenPermanent"
                                checked={formData.citizenPermanent || false} onChange={handleChange}
                            />
                            <Form.Check
                                inline type="checkbox" label="Aucun des éléments ci-dessus" name="citizenNone"
                                checked={formData.citizenNone || false} onChange={handleChange}
                            />
                        </div>
                        {!(formData.citizenUS || formData.citizenPermanent || formData.citizenNone) && <div className="invalid-feedback d-block">Le statut de citoyenneté est requis.</div>}
                    </Form.Group>
                </div>
            )}

            {/* --- 2. Educational Background --- */}
            <CollapsibleHeader
                title="2. Formation académique"
                isOpen={isEducationalInfoOpen}
                onToggle={() => setIsEducationalInfoOpen(!isEducationalInfoOpen)}
                sectionId="educational-info"
            />
            {isEducationalInfoOpen && (
                <div id="collapse-educational-info" style={{ paddingTop: '0.5rem' }}>
                    <Form.Group className="mb-3">
                        <Form.Label>2.1 Niveau d'éducation le plus élevé</Form.Label>
                        <div
                            onBlur={() => handleSectionFieldBlur('educationalInfo', isEducationalInfoOpen, setIsEducationalInfoOpen, 'educationalInfo')}
                            className="mb-4" // Added mb-4 to the div wrapping checkboxes
                        >
                            <Form.Check inline type="checkbox" label="Diplôme d’Études Secondaires (High School Diploma)" name="eduHighSchool" checked={formData.eduHighSchool || false} onChange={handleChange} />
                            <Form.Check inline type="checkbox" label="Certificat (Sous-licence ou Professionnel/Technique)" name="eduCertificate" checked={formData.eduCertificate || false} onChange={handleChange} />
                            <Form.Check inline type="checkbox" label="Diplôme (Sous-licence ou Professionnel/Technique)" name="eduDiploma" checked={formData.eduDiploma || false} onChange={handleChange} />
                            <Form.Check inline type="checkbox" label="Diplôme d’Associé (Associate Degree)" name="eduAssociate" checked={formData.eduAssociate || false} onChange={handleChange} />
                            <Form.Check inline type="checkbox" label="Licence/Baccalauréat (Bachelor’s Degree)" name="eduBachelor" checked={formData.eduBachelor || false} onChange={handleChange} />
                            <Form.Check inline type="checkbox" label="Master (Master’s Degree)" name="eduMaster" checked={formData.eduMaster || false} onChange={handleChange} />
                            <Form.Check inline type="checkbox" label="Doctorat (PhD)" name="eduDoctorate" checked={formData.eduDoctorate || false} onChange={handleChange} />
                        </div>
                        {!(formData.eduHighSchool || formData.eduCertificate || formData.eduDiploma || formData.eduAssociate || formData.eduBachelor || formData.eduMaster || formData.eduDoctorate) && <div className="invalid-feedback d-block">Le niveau d'éducation le plus élevé est requis.</div>}
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>2.2.1 Nom de l'établissement</Form.Label>
                        <Form.Control type="text" name="applicantSchoolName" value={formData.applicantSchoolName || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('educationalInfo', isEducationalInfoOpen, setIsEducationalInfoOpen, 'educationalInfo')} placeholder="Nom de l'établissement" className="form-control mb-4" />
                        {!formData.applicantSchoolName && <div className="invalid-feedback d-block">Le nom de l'établissement est requis.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>2.2.2 Période d'inscription</Form.Label>
                        <Form.Control type="text" name="applicantEnrollmentTerm" value={formData.applicantEnrollmentTerm || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('educationalInfo', isEducationalInfoOpen, setIsEducationalInfoOpen, 'educationalInfo')} placeholder="jj/mm/aaaa à jj/mm/aaaa" className="form-control mb-4" />
                        {!formData.applicantEnrollmentTerm && <div className="invalid-feedback d-block">La période d'inscription est requise.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>2.2.3 Domaine d'études principal</Form.Label>
                        <Form.Control type="text" name="applicantMajor" value={formData.applicantMajor || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('educationalInfo', isEducationalInfoOpen, setIsEducationalInfoOpen, 'educationalInfo')} placeholder="Spécialisation ou domaine d'études" className="form-control mb-4" />
                        {!formData.applicantMajor && <div className="invalid-feedback d-block">Le domaine d'études principal est requis.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>2.3 Langues supplémentaires</Form.Label>
                        <Form.Control type="text" name="applicantLanguages" value={formData.applicantLanguages || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('educationalInfo', isEducationalInfoOpen, setIsEducationalInfoOpen, 'educationalInfo')} placeholder="Langues supplémentaires parlées (ou N/A)" className="form-control mb-4" />
                        {!formData.applicantLanguages && <div className="invalid-feedback d-block">Ce champ est requis (entrez N/A si aucune).</div>}
                    </Form.Group>
                </div>
            )}

            {/* --- 3. Employment History --- */}
            <CollapsibleHeader
                title="3. Expérience professionnelle"
                isOpen={isEmploymentInfoOpen}
                onToggle={() => setIsEmploymentInfoOpen(!isEmploymentInfoOpen)}
                sectionId="employment-info"
            />
            {isEmploymentInfoOpen && (
                <div id="collapse-employment-info" style={{ paddingTop: '0.5rem' }}>
                    <Form.Group className="mb-3">
                        <Form.Label>3.1 Emploi précédent</Form.Label>
                        <Form.Control type="text" name="applicantPrevEmployment" value={formData.applicantPrevEmployment || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('employmentInfo', isEmploymentInfoOpen, setIsEmploymentInfoOpen, 'employmentInfo')} placeholder="RÔLE chez ENTREPRISE entre jj/mm/aaaa et jj/mm/aaaa (ou N/A)" className="form-control mb-4" />
                        {!formData.applicantPrevEmployment && <div className="invalid-feedback d-block">Ce champ est requis (entrez N/A si aucun).</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>3.2 Fonctions</Form.Label>
                        <Form.Control as="textarea" rows={3} name="applicantPrevDuties" value={formData.applicantPrevDuties || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('employmentInfo', isEmploymentInfoOpen, setIsEmploymentInfoOpen, 'employmentInfo')} placeholder="Description de la fonction précédente (ou N/A)" className="form-control mb-4" />
                        {!formData.applicantPrevDuties && <div className="invalid-feedback d-block">Ce champ est requis (entrez N/A si aucune).</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>3.3 Motif du départ (le cas échéant)</Form.Label>
                        <Form.Control as="textarea" rows={2} name="applicantPrevDismissalReason" value={formData.applicantPrevDismissalReason || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('employmentInfo', isEmploymentInfoOpen, setIsEmploymentInfoOpen, 'employmentInfo')} placeholder="Motif du départ de l'emploi précédent (ou N/A)" className="form-control mb-4" />
                        {/* No validation message for optional field, but added mb-4 */}
                    </Form.Group>
                </div>
            )}

            {/* --- 4. Motivational Letter --- */}
            <CollapsibleHeader
                title="4. Lettre de motivation"
                isOpen={isMotivationalLetterOpen}
                onToggle={() => setIsMotivationalLetterOpen(!isMotivationalLetterOpen)}
                sectionId="motivational-letter"
            />
            {isMotivationalLetterOpen && (
                <div id="collapse-motivational-letter" style={{ paddingTop: '0.5rem' }}>
                    <Form.Group className="mb-3">
                        <Form.Label>4.1 Lettre de motivation</Form.Label>
                        <Form.Control
                            as="textarea" rows={8} name="applicantMotivationLetter" value={formData.applicantMotivationLetter || ''}
                            onChange={handleChange} onBlur={() => handleSectionFieldBlur('motivationalLetter', isMotivationalLetterOpen, setIsMotivationalLetterOpen, 'motivationalLetter')}
                            placeholder="Décrivez pourquoi vous souhaitez nous rejoindre, pourquoi nous devrions vous choisir plutôt qu'une autre personne, et pourquoi les qualités requises pour ce poste vous correspondent" className="form-control mb-4"
                        />
                        {!formData.applicantMotivationLetter && <div className="invalid-feedback d-block">La lettre de motivation est requise.</div>}
                    </Form.Group>
                </div>
            )}

            {/* --- 5. (( Out of Character information )) --- */}
            <CollapsibleHeader
                title="5. (( Informations hors personnage ))"
                isOpen={isOocInfoOpen}
                onToggle={() => setIsOocInfoOpen(!isOocInfoOpen)}
                sectionId="ooc-info"
            />
            {isOocInfoOpen && (
                <div id="collapse-ooc-info" style={{ paddingTop: '0.5rem' }}>
                    <Form.Group className="mb-3">
                        <Form.Label>5.1 Nom d'utilisateur du panneau de contrôle utilisateur (UCP)</Form.Label>
                        <Form.Control type="text" name="oocUcpName" value={formData.oocUcpName || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('oocInfo', isOocInfoOpen, setIsOocInfoOpen, 'oocInfo')} className="form-control mb-4" />
                        {!formData.oocUcpName && <div className="invalid-feedback d-block">Le nom d'utilisateur UCP est requis.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>5.2 Nom de compte du forum GTA:W</Form.Label>
                        <Form.Control type="text" name="oocForumName" value={formData.oocForumName || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('oocInfo', isOocInfoOpen, setIsOocInfoOpen, 'oocInfo')} required className={`form-control ${!formData.oocForumName ? 'is-invalid' : ''} mb-4`} />
                        {!formData.oocForumName && <div className="invalid-feedback d-block">Le nom du forum est requis.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>5.3 Nom Discord</Form.Label>
                        <Form.Control type="text" name="oocDiscord" value={formData.oocDiscord || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('oocInfo', isOocInfoOpen, setIsOocInfoOpen, 'oocInfo')} required className={`form-control ${!formData.oocDiscord ? 'is-invalid' : ''} mb-4`} />
                        {!formData.oocDiscord && <div className="invalid-feedback d-block">Le nom Discord est requis.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>5.4 Fuseau horaire</Form.Label>
                        <Form.Control type="text" name="oocTimezone" value={formData.oocTimezone || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('oocInfo', isOocInfoOpen, setIsOocInfoOpen, 'oocInfo')} placeholder="ex: UTC+0, EST, PST" className="form-control mb-4" />
                        {!formData.oocTimezone && <div className="invalid-feedback d-block">Le fuseau horaire est requis.</div>}
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>5.5 Expérience médicale réelle ou RP médical passé</Form.Label>
                        <Form.Control as="textarea" rows={3} name="oocMedicalExperience" value={formData.oocMedicalExperience || ''} onChange={handleChange} onBlur={() => handleSectionFieldBlur('oocInfo', isOocInfoOpen, setIsOocInfoOpen, 'oocInfo')} placeholder="Décrivez toute expérience pertinente" className="form-control mb-4" />
                        {!formData.oocMedicalExperience && <div className="invalid-feedback d-block">Ce champ est requis.</div>}
                    </Form.Group>
                </div>
            )}
        </>
    );
};

export default PhysicianFields;
